node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search across all booking-like tables for BK-B70889
const fb = db.prepare(\"SELECT * FROM flight_bookings WHERE booking_id = ?\").get('BK-B70889');
const hr = db.prepare(\"SELECT * FROM hotel_reservations WHERE reservation_id = ?\").get('BK-B70889');
const cr = db.prepare(\"SELECT * FROM car_rentals WHERE rental_id = ?\").get('BK-B70889');

if (fb) { console.log('=== Flight Booking ==='); console.log(JSON.stringify(fb, null, 2)); }
if (hr) { console.log('=== Hotel Reservation ==='); console.log(JSON.stringify(hr, null, 2)); }
if (cr) { console.log('=== Car Rental ==='); console.log(JSON.stringify(cr, null, 2)); }
if (!fb && !hr && !cr) { console.log('Booking not found in flight_bookings, hotel_reservations, or car_rentals'); }
"

